self.KB_CONTENT["card:756836"]={"id":"card:756836","ty":"card","sourceId":"756836","title":"『訂單資訊查詢作業』的作業重點有哪些？","ver":"iGP","topic":"訂單","keywords":["訂單","資訊","轉出","結果"],"y":"explain","answer":"1.設定好查詢條件後，按「查詢」將結果顯示於最後一個分頁。2.本作業目的為提供線上即時查詢故不提供列印功能，查詢結果如有列出報表之需求，可利用功能鈕轉出Excel編修列印。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
