self.KB_CONTENT["card:751895"]={"id":"card:751895","ty":"card","sourceId":"751895","title":"『科目餘額/預算查詢作業』中的『選擇期別』為何？","ver":"iGP","topic":"科目","keywords":["科目","預算","餘額"],"y":"other","answer":"* 選擇期別(起)預設為『01』。* 會計期制分為12期(01-12)及13期(01-13)。關係人餘額","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
