self.KB_CONTENT["card:792692"]={"id":"card:792692","ty":"card","sourceId":"792692","title":"『受訂確認書』中的『選擇排序』為何？","ver":"GP4以上","topic":"品號","keywords":["品號","訂單","單號","序號"],"y":"other","answer":"* 列印時報表之排序方式，分別為1.訂單單號+品號+預交日、2.訂單單號+序號+品號+預交日。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
