self.KB_CONTENT["card:778894"]={"id":"card:778894","ty":"card","sourceId":"778894","title":"『出貨通知單建立作業(IDL)』中的『運輸方式 (TA031)』為何？","ver":"GP4以上","topic":"出貨","keywords":["出貨"],"y":"other","answer":"* 可點選(icon)或[F2]運輸方式代號查詢(CMSNJ-01)，並顯示運輸方式中文名稱。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
