self.KB_CONTENT["field:781735"]={"id":"field:781735","ty":"field","sourceId":"781735","title":"訂單單號","ver":"GP4以上","topic":"","keywords":[],"job":"材料需求檢視表","code":"COP.TC002","answer":"* 不可空白。* 選擇後，請按選項左方的「向左箭頭」的圖示，將【訂單單別】、【訂單單號】、【訂單序號】放入左方的「選擇訂單編號」中。","file":"fields.jsonl"};
